          "script": "(function execute() {\n    //Check if topic was triggered from Issue Auto Resolution\n    var gr = new GlideRecord('sys_cs_auto_resolution_context');\n    gr.addQuery('interaction', vaVars._interaction_record_sysid);\n    gr.query();\n    vaVars.is_interaction_through_auto_resolution = gr.next();\n})()\n",
